class UndoableText:
    """Undo with a stack of previous states (the most recent change is undone first)."""
    def __init__(self):
        self.text = ""
        self.history = []

    def type(self, s):
        self.history.append(self.text)
        self.text += s

    def undo(self):
        if self.history:
            self.text = self.history.pop()
