    for case in trials:
        if greedy(case) != exact(case):
            return case
    return None

def max_sum_of_k_distinct_greedy(nums, k):
    return sum(sorted(nums, reverse=True)[:k])     # greedy: take the k largest

def max_sum_of_k_exact(nums, k):
