    int total = 0, tank = 0, start = 0;
    for (int i = 0; i < (int)gas.size(); i++) {
        int diff = gas[i] - cost[i];
        total += diff;
        tank += diff;
        if (tank < 0) {                            // can't get past i from `start`
            start = i + 1;
            tank = 0;
        }
    }
    return total < 0 ? -1 : start;
}
